function routeSegments(r){const out=[];r.legs.forEach((l,i)=>{if(isMissedApproachLeg(r.legs,i))return;const key=l.disco?'':l.procedure||l.via||'';const previous=out.at(-1);if(key&&previous?.key===key&&previous.source===l.source){previous.end=i;previous.leg=l;}else out.push({start:i,end:i,key,source:l.source,leg:l});});return out;}
function deleteSegment(segment){if(!segment)throw Error('INVALID DELETE');const r=e.route;if(segment.start<r.index||e.activated&&segment.start===r.index||r.legs.slice(segment.start,segment.end+1).some(l=>l.manual||l.disco))throw Error('INVALID DELETE');e.draft().legs.splice(segment.start,segment.end-segment.start+1,disco());e.log('MOD · removed route segment '+segment.leg.id);}
