function takeoffInputs(){const p=e.perf,w=p.runwayWind||'H00/U0.0',m=w.match(/^([HT])(\d{1,3})\/([UD])(\d(?:\.\d)?)$/);return {grossWeight:grossWeight(),flaps:p.flaps,mode:p.n1||'TO',pressureAltitude:p.takeoffPA??db.airports[e.route.origin]?.elevation??0,oat:Number(p.oat||15),assumedTemp:p.assumedTemp||'',condition:p.runwayCondition||'DRY',wind:m?(m[1]==='T'?-1:1)*+m[2]:NaN,slope:m?(m[3]==='D'?-1:1)*+m[4]:NaN};}
