function candidates(id){if(id==='PPOS')return [{id,lat:e.aircraft.lat,lon:e.aircraft.lon,type:'POSITION'}];const exact=id.trim().toUpperCase();let f=db.fixes[exact]||[];if(!f.length&&exact.length===3){const a='K'+exact;if(db.index.some(x=>x.id===a))f=[db.index.find(x=>x.id===a)];}const scoped=f.filter(x=>!x.scope||[e.route.origin,e.route.destination].includes(x.scope));return (scoped.length?scoped:f).slice().sort((a,b)=>distance(e.aircraft,a)-distance(e.aircraft,b));}
async function withFix(id,callback){await ensureFixes();const fs=candidates(id);if(!fs.length){const p=pilotWaypoint(id);if(!p)throw Error('NOT IN DATABASE');callback(p);return;}if(fs.length===1){callback(fs[0]);return;}selectContext={fs,callback,returnPage:page,returnNo:pageNo};go('SELECT DESIRED WPT');}
