function setOriginDest(key){if(!scratch){copy(e.route[key]);return;}const id=airportID(take());return airport(id).then(a=>{if(a.id===e.route[key==='origin'?'destination':'origin'])throw Error('INVALID ENTRY');const r=e.draft();r[key]=id;if(key==='origin'){r.sid='';r.sidTrans='';r.runway='';}else{r.star='';r.starTrans='';r.approach='';r.appTrans='';r.arrivalRunway='';}e.rebuild(db.airports);e.log(`MOD · ${key} ${id}`);});}
function appLabel(id){if(/^RW\d{2}/.test(id))return id.slice(2);const m=id.match(/^([A-Z])(\d{2})([LRC]?)-?([A-Z]?)$/);const map={I:'ILS',R:'RNP',H:'RNP',L:'LOC',V:'VOR ',N:'NDB',G:'GPS',D:'VOR/DME',Q:'NDB/DME',S:'SDF'};if(!m)return (map[id[0]]||id[0])+id.slice(1).replace(/-/g,'');return (map[m[1]]||m[1])+m[2]+m[3]+m[4];}
function approachOrder(a,b){const rank=id=>({I:0,R:1,H:2,V:3,L:4,N:5}[id[0]]??6);return rank(a)-rank(b)||appLabel(a).localeCompare(appLabel(b));}
function databaseDates(){const start=new Date((db.meta.effective||'2026-09-03')+'T00:00:00Z'),end=new Date((db.meta.expires||'2026-10-01')+'T00:00:00Z');const fmt=d=>['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'][d.getUTCMonth()]+String(d.getUTCDate()).padStart(2,'0');const range=(a,b)=>fmt(a)+fmt(b)+'/'+String(b.getUTCFullYear()).slice(-2);return {active:range(start,new Date(+end-86400000)),previous:range(new Date(+start-28*86400000),new Date(+start-86400000))};}
