function appRunway(id){return id.match(/^[A-Z](\d{2}[LRC]?)/)?.[1]||'';}
function setRunway(id,arrival=false){const r=e.draft();if(arrival){r.arrivalRunway=id;if(r.approach&&'RW'+appRunway(r.approach)!==id){r.approach='';r.appTrans='';}}else{r.runway=id;const p=db.airports[r.origin]?.procedures.D[r.sid];if(p){const rw=p.segments.filter(s=>'147'.includes(s.type));if(rw.length&&!rw.some(s=>runwayMatch(s.transition,id))){r.sid='';r.sidTrans='';}}}e.rebuild(db.airports);e.log(`MOD · ${arrival?'arrival':'departure'} runway ${id.slice(2)}`);}
function selectProc(cat,id){if(cat!=='D'&&arrivalAirportOverride&&arrivalAirportOverride!==e.route.destination){toast('Origin-arrival procedures are view-only in this trainer.');return;}const deleting=scratch==='DELETE';if(deleting)clear();const r=e.draft();const key={D:'sid',E:'star',F:'approach'}[cat],tr={D:'sidTrans',E:'starTrans',F:'appTrans'}[cat];if(deleting){r[key]='';r[tr]='';e.rebuild(db.airports);e.log('MOD · removed '+id);return;}r[key]=id;r[tr]='';if(cat==='F'){const rw=appRunway(id);if(rw)r.arrivalRunway='RW'+rw;}e.rebuild(db.airports);e.log(`MOD · selected ${cat==='D'?'SID':cat==='E'?'STAR':'approach'} ${id}`);procContext={cat,id};go('TRANSITIONS');}
