function buildProcedures(r){
 const arrival=page==='ARRIVALS',id=arrival?(arrivalAirportOverride||r.destination):r.origin,a=db.airports[id],cat=arrival?'E':'D',selected=arrival?r.star:r.sid,transKey=arrival?'starTrans':'sidTrans';
 if(!a){title(arrival?'ARRIVALS':'DEPARTURES');foot('<INDEX','ROUTE>',()=>go('DEP/ARR'),()=>go('RTE'));return;}
 const readOnly=arrival&&id!==r.destination;
 const change=fn=>{if(readOnly){notModeled('Loading an arrival for the origin');return;}fn();};
 const mark=(key,val)=>(e.activated&&e.active[key]===val?'<ACT>':'<SEL>');
 let left=[],right=[];
 const chooseProcedure=(kind,name,already)=>()=>change(()=>{if(already){clear();const dr=e.draft(),k={D:'sid',E:'star',F:'approach'}[kind],tk={D:'sidTrans',E:'starTrans',F:'appTrans'}[kind];dr[k]='';dr[tk]='';if(kind==='F')dr.arrivalRunway='';e.rebuild(db.airports);pageNo=0;}else selectProc(kind,name);});
 let leftFixed=null,rightFixed=null;
 if(selected&&a.procedures[cat][selected]&&!readOnly){
 leftFixed={label:arrival?'STARS':'SIDS',value:selected+' '+mark(arrival?'star':'sid',selected),fn:chooseProcedure(cat,selected,true)};
 let opts=transOptions(cat,a.procedures[cat][selected]);if(r[transKey])opts=opts.filter(t=>t===r[transKey]);
 left=opts.map((t,i)=>({label:i===0?'TRANS':'',value:t+(r[transKey]===t?' '+mark(transKey,t):''),fn:()=>{const d=e.draft();d[transKey]=d[transKey]===t?'':t;e.rebuild(db.airports);pageNo=0;}}));
 }else{
 let names=Object.keys(a.procedures[cat]).sort();if(!arrival&&r.runway)names=names.filter(n=>{const seg=a.procedures.D[n].segments.filter(v=>'147'.includes(v.type));return !seg.length||seg.some(v=>runwayMatch(v.transition,r.runway));});
 if(arrival&&r.arrivalRunway)names=names.filter(n=>{const seg=a.procedures.E[n].segments.filter(v=>'369'.includes(v.type));return !seg.length||seg.some(v=>runwayMatch(v.transition,r.arrivalRunway));});
 left=names.map((n,i)=>({label:i===0?(arrival?'STARS':'SIDS'):'',value:n,fn:chooseProcedure(cat,n,false)}));
 }
 if(arrival&&r.approach&&a.procedures.F[r.approach]&&!readOnly){
 rightFixed={label:'APPROACHES',value:mark('approach',r.approach)+' '+appLabel(r.approach),fn:chooseProcedure('F',r.approach,true)};
 let opts=transOptions('F',a.procedures.F[r.approach]);if(r.appTrans)opts=opts.filter(t=>t===r.appTrans);
 right=opts.map((t,i)=>({label:i===0?'TRANS':'',value:(r.appTrans===t?mark('appTrans',t)+' ':'')+t,fn:()=>{const d=e.draft();d.appTrans=d.appTrans===t?'':t;e.rebuild(db.airports);pageNo=0;}}));
 }else if((arrival?r.arrivalRunway:r.runway)&&!readOnly){
 const key=arrival?'arrivalRunway':'runway',rw=r[key];rightFixed={label:'RUNWAYS',value:mark(key,rw)+' '+rw.slice(2),fn:()=>{e.draft()[key]='';e.rebuild(db.airports);pageNo=0;}};
 }else{
 if(arrival)right=Object.keys(a.procedures.F).sort(approachOrder).map((n,i)=>({label:i===0?'APPROACHES':'',value:appLabel(n),fn:chooseProcedure('F',n,false)}));
 let runways=a.runways;if(!arrival&&r.sid){const seg=a.procedures.D[r.sid]?.segments.filter(v=>'147'.includes(v.type))||[];if(seg.length)runways=runways.filter(w=>seg.some(v=>runwayMatch(v.transition,w.id)));}
 right.push(...runways.map((rw,i)=>({label:i===0?'RUNWAYS':'',value:rw.id.slice(2),fn:()=>change(()=>{clear();setRunway(rw.id,arrival);pageNo=0;})})));
 }
 const lc=leftFixed?4:5,rc=rightFixed?4:5;title(`${a.id} ${arrival?'ARRIVALS':'DEPARTURES'}`,Math.max(1,Math.ceil(left.length/lc),Math.ceil(right.length/rc)));
 const fill=(side,fixed,entries,count)=>{const selectedRows=fixed?[fixed,...entries.slice(pageNo*count,pageNo*count+count)]:entries.slice(pageNo*count,pageNo*count+count);selectedRows.forEach((x,i)=>{if(side==='L'){rows[i].ll=x.label;rows[i].lv=x.value;rows[i].left=x.fn;}else{rows[i].rl=x.label;rows[i].rv=x.value;rows[i].right=x.fn;}});};
 fill('L',leftFixed,left,lc);fill('R',rightFixed,right,rc);foot('<INDEX','ROUTE>',()=>go('DEP/ARR'),()=>go('RTE'));
}

