 row(2,'RUNWAY',r.runway.replace('RW','')||'---','','',()=>{if(!scratch){if(r.runway)copy(r.runway.slice(2));return;}const id='RW'+take().replace(/^RW/,'');if(!db.airports[r.origin]?.runways.some(x=>x.id===id))throw Error('NOT IN DATABASE');setRunway(id);});
