function openHold(){holdIndex=e.route.legs.findIndex((l,i)=>i>=e.route.index&&l.hold);go(holdIndex>=0?'HOLD':'HOLD AT');}
async function lsk(side,i){
 if(!e||busy||message)return;sessionStarted=true;const original=scratch;
 try{busy=true;const fn=rows[i]?.[side==='L'?'left':'right'];if(fn)await fn();else if(scratch==='DELETE')throw Error('INVALID DELETE');}
 catch(err){scratch=original;message=err.message==='NOT IN DATABASE'?'NOT IN DATA BASE':err.message||'INVALID ENTRY';}
 finally{busy=false;render();}
}
function key(k){if(!e||busy)return;sessionStarted=true;if(k==='CLR'){if(message)message='';else if(scratch==='DELETE')scratch='';else scratch=scratch.slice(0,-1);render();return;}if(k==='DEL'){scratch='DELETE';message='';render();return;}if(k==='SP'){input(' ');return;}if(k==='+/-'){if(message||scratch==='DELETE')clear();if(scratch.length>=24&&!/[+-]$/.test(scratch))return;if(scratch.endsWith('-'))scratch=scratch.slice(0,-1)+'+';else if(scratch.endsWith('+'))scratch=scratch.slice(0,-1)+'-';else scratch+='-';render();return;}if(k==='EXEC'){if(e.execute())toast('Route changes executed');render();return;}if(k==='VNAV'){go(e.aircraft.phase==='arrival'?'DES':e.aircraft.phase==='cruise'?'CRZ':'CLB');return;}if(k==='NEXT PAGE'||k==='PREV PAGE'){if(['CLB','CRZ','DES'].includes(page)){go(['CLB','CRZ','DES'][(pageNo+(k==='NEXT PAGE'?1:2))%3]);return;}pageNo=(pageNo+(k==='NEXT PAGE'?1:-1)+totalPages)%totalPages;render();return;}if(k==='HOLD'){openHold();return;}if(k==='DEP ARR'){arrivalAirportOverride=null;if(['DEPARTURES','ARRIVALS','DEP/ARR'].includes(page)||!e.route.origin)go('DEP/ARR');else if(e.aircraft.phase==='preflight')go('DEPARTURES');else go('ARRIVALS');return;}if(k==='INIT REF'){go(e.aircraft.phase==='preflight'?(!e.pos.irs?'IDENT':'PERF INIT'):'APPROACH REF');return;}const map={'INIT REF':'INDEX','DEP ARR':'DEP/ARR','PROG':'PROGRESS'};if(['INIT REF','RTE','CLB','CRZ','DES','MENU','LEGS','DEP ARR','FIX','PROG','N1 LIMIT','ATC','FMC COMM'].includes(k)){go(map[k]||k);return;}input(k);}
function screenRowHTML(x){return `<div class="screen-row ${x.legRow?'leg-row':''} ${x.trimValue?'trim-row':''} ${x.color||''}"><div class="row-labels"><span class="${/^[- ]{10,}$/.test(x.ll)?'rule-line':''}">${esc(x.fullLabel?'':x.ll)}</span><span class="center-label ${x.fullLabel?'full-label':''}">${esc(x.fullLabel||x.cl||'')}</span><span>${esc(x.rl)}</span></div><div class="row-values"><span class="${String(x.lv).length>22?'small-value':''}">${esc(x.fullValue?'':x.lv)}</span><span class="center-value ${x.trimValue?'trim-value':''} ${x.fullValue?'full-value':''}">${esc(x.fullValue||x.trimValue||x.cv||'')}</span><span class="right-value ${String(x.rv).length>17?'small-value':''} ${x.rightReverse?'reverse-value':''}">${x.fullValue?'':(x.refSpeed?`<span class="reference-speed">${esc(x.refSpeed)}</span>`:'')+`<span>${esc(x.rv)}</span>`}</span></div></div>`;}
function render(){if(!e)return;buildPage();if(page==='LEGS'&&e.execPending)$('screen-title').innerHTML=esc($('screen-title').textContent).replace(/^MOD /,'<span class="modified-word">MOD</span> ');$('screen-rows').innerHTML=rows.map(screenRowHTML).join('');$('scratch-text').textContent=message||scratch;$('scratchpad').classList.toggle('error',!!message);$('message-light').classList.toggle('on',!!message);$('exec-light').classList.toggle('on',e.execPending);document.querySelector('[data-key="EXEC"]').classList.toggle('lit',e.execPending);if(FMCUI.afterRender)FMCUI.afterRender();}
